from collections import Counter

class Solution:
    def digitCount(self, num: str) -> bool:
        counts = Counter(num)
        for i, ch in enumerate(num):
            if counts[str(i)] != int(ch):
                return False
        return True

class Solution {
public:
    bool digitCount(std::string num) {
        std::vector<int> counts(10, 0);
        for (char c : num) counts[c - '0']++;
        for (int i = 0; i < (int)num.size(); ++i) {
            if (counts[i] != num[i] - '0') return false;
        }
        return true;
    }
};

class Solution {
    public boolean digitCount(String num) {
        int[] counts = new int[10];
        for (char c : num.toCharArray()) counts[c - '0']++;
        for (int i = 0; i < num.length(); i++) {
            if (counts[i] != num.charAt(i) - '0') return false;
        }
        return true;
    }
}

var digitCount = function(num) {
    const counts = new Int32Array(10);
    for (let i = 0; i < num.length; i++) counts[num.charCodeAt(i) - 48]++;
    for (let i = 0; i < num.length; i++) {
        if (counts[i] !== num.charCodeAt(i) - 48) return false;
    }
    return true;
};
